def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 98:
        return 'D'

    my_last, opp_last = history[-1]

    opp_def = 0
    my_def = 0
    for i in range(n):
        m, o = history[i]
        if o == 'D':
            opp_def += 1
        if m == 'D':
            my_def += 1

    exploit = 0
    forgiven = 0
    punished = 0
    for i in range(1, n):
        prev_m = history[i - 1][0]
        cur_o = history[i][1]
        if cur_o == 'D' and prev_m == 'C':
            exploit += 1
        if prev_m == 'D':
            if cur_o == 'C':
                forgiven += 1
            else:
                punished += 1

    opp_d_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opp_d_streak += 1
        else:
            break

    recent_len = 8 if n >= 8 else n
    recent_opp_def = 0
    for i in range(n - recent_len, n):
        if history[i][1] == 'D':
            recent_opp_def += 1

    if opp_d_streak >= 2:
        return 'D'
    if recent_opp_def >= 4 and opp_def >= 3:
        return 'D'
    if opp_def >= 3 and opp_def >= n // 2:
        return 'D'

    if opp_last == 'D':
        if n >= 2 and history[-2][0] == 'D':
            if opp_def <= 6 and punished <= 4:
                return 'C'
            return 'D'
        if opp_def >= 5 or exploit >= 4:
            return 'D'
        return 'C'

    if punished == 0 and forgiven >= 1 and my_last == 'C':
        if n >= 3 and history[-2][0] == 'D':
            if opp_def <= max(2, n // 10) and my_def > opp_def:
                return 'D'

    if n >= 6 and my_def == 0 and opp_def <= 1 and recent_opp_def <= 1:
        return 'D'

    return 'C'
